<include file="Public:header"/><div class="mainbox">	<div id="nav" class="mainnav_title">		<ul>			<a href="{pigcms{:U('Shop/discount',array('shop_type'=>$_GET['shop_type']))}">外卖优惠列表</a>|			<a href="{pigcms{:U('Shop/merchant',array('shop_type'=>$_GET['shop_type'],'id'=>$_GET['id']))}" class="on">指定店铺</a>		</ul>	</div>	<table class="search_table" width="100%">		<tr>			<td style="width:60%;">				<form action="{pigcms{:U('Shop/merchant', array('id' => $did))}" method="get">					<input type="hidden" name="c" value="Shop"/>					<input type="hidden" name="id" value="{pigcms{$did}"/>					<input type="hidden" name="a" value="merchant"/>					<select name="status">						<option value="0" <if condition="$status eq 0">selected="selected"</if>>全部</option>						<option value="1" <if condition="$status eq 1">selected="selected"</if>>已指定</option>						<option value="2" <if condition="$status eq 2">selected="selected"</if>>指定</option>					</select>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;					<select name="searchtype">						<option value="store_name" <if condition="$_GET['searchtype'] eq 'store_name'">selected="selected"</if>>店铺名称</option>						<option value="store_id" <if condition="$_GET['searchtype'] eq 'store_id'">selected="selected"</if>>店铺编号</option>						<option value="name" <if condition="$_GET['searchtype'] eq 'name'">selected="selected"</if>>商家名称</option>						<option value="phone" <if condition="$_GET['searchtype'] eq 'phone'">selected="selected"</if>>联系电话</option>						<option value="mer_id" <if condition="$_GET['searchtype'] eq 'mer_id'">selected="selected"</if>>商家编号</option>					</select>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;					<input type="text" name="keyword" class="input-text" value="{pigcms{$_GET['keyword']}"/>					<input type="submit" value="查询" class="button"/>				</form>			</td>		</tr>	</table>	<form name="myform" id="myform" action="" method="post">		<div class="table-list">			<table width="100%" cellspacing="0">				<thead>					<tr>						<th width="60"><input type="checkbox" id="all"/></th>						<th width="60">编号</th>						<th width="120">商家名称</th>						<th width="120">店铺名称</th>						<!-- <th>指定店铺</th> -->						<th width="140">联系电话</th>						<th width="140">操作</th>					</tr>				</thead>				<tbody>					<if condition="is_array($storeList)">						<volist name="storeList" id="vo">							<tr>								<td store_id="{pigcms{$vo.store_id}"><input type="checkbox" name="merIds[]" class="mer_id_{pigcms{$vo.mer_id} store_id_{pigcms{$vo.store_id}" value="{pigcms{$vo.mer_id}" <if condition="!empty($vo['is_bind'])">checked</if>></td>								<td>{pigcms{$vo.store_id}</td>								<td>{pigcms{$vo.merchant_name}</td>								<td>{pigcms{$vo.name}</td>								<!-- <td>									<span style="color:red;cursor:pointer;margin-top:8px;display:block;" class="choose_store" data-mer_id="{pigcms{$vo.mer_id}">[指定店铺]</span>									<input type="hidden" name="storeIds[{pigcms{$vo.mer_id}][]" class="storeIds storeIds_{pigcms{$vo.mer_id}" data-mer_id="{pigcms{$vo.mer_id}" value="{pigcms{$vo.store_ids}"/>									<if condition="$vo['store_names']"><p class="storeNames_{pigcms{$vo.mer_id}">{pigcms{$vo.store_names}</p></if>								</td> -->								<td>{pigcms{$vo.phone}</td>								<td class="textcenter" data-id="{pigcms{$vo.mer_id}" data-store_id="{pigcms{$vo.store_id}">									<span class="cb-enable"><label class="cb-enable <if condition="!empty($vo['is_bind'])">selected</if>"><span>指定</span><input type="radio" name="selectMerchant{pigcms{$vo['store_id']}" value="1" <if condition="!empty($vo['is_bind'])">checked="checked"</if> /></label></span>									<span class="cb-disable"><label class="cb-disable <if condition="empty($vo['is_bind'])">selected</if>"><span>解除指定</span><input type="radio" name="selectMerchant{pigcms{$vo['store_id']}" value="0" <if condition="empty($vo['is_bind'])">checked="checked"</if>/></label></span>								</td>							</tr>						</volist>						<tr>							<td class="textcenter pagebar" colspan="12">								<input type="button" value="批量指定" id="online" class="button" style="float:left;margin-right:20px;margin-top:2px;"/>								<input type="button" value="批量解除指定" id="offline" class="button" style="float:left;margin-top:2px;"/>								{pigcms{$pagebar}							</td>						</tr>					<else/>						<tr><td class="textcenter red" colspan="12">列表为空！</td></tr>					</if>				</tbody>			</table>		</div>	</form></div><script type="text/javascript">$(document).ready(function(){    $('#all').click(function(){        if ($(this).is(':checked')) {            $('input[type="checkbox"]').attr('checked', true);        } else {            $('input[type="checkbox"]').attr('checked', false);        }    });	/* $('input[type="checkbox"]').change(function(){		var mer_id = $(this).val();		$('.storeIds_'+mer_id).val('');		$('.storeNames_'+mer_id).remove();	}); */    var did = '{pigcms{$did}';    $('input[type="radio"]').click(function(){        var merIds = [], mer_id = $(this).parents('td').data('id'),store_id = $(this).parents('td').data('store_id'), obj = $(this).parents('tr').find('input[type="checkbox"]');        var type = $(this).val();		var storeIds = {};        merIds.push(mer_id);        // storeIds.push(store_id);				storeIds[mer_id] = store_id;				// $.each($('.storeIds_' + mer_id),function(i,item){		// 	if($(item).val() != ''){		// 		storeIds[mer_id] = $(item).val();		// 	}		// });		        $.post('{pigcms{:U("Shop/change")}', {'did':did, 'type':type,'merIds':merIds,'storeIds':storeIds}, function(res){            if (res.status == 1) {				layer.msg(res.info,{offset:'10px',shift:6,time:2000});                if (type == 1) {                    obj.attr('checked', true);                } else {                    obj.attr('checked', false);                }            } else {                alert(res.info);            }        }, 'json');    });    $('#online').click(function(){        var merIds = [];		var storeIds = {};        $("input[name='merIds[]']:checked").each(function(){            merIds.push($(this).val());            if (storeIds[$(this).val()]) {				storeIds[$(this).val()] += $(this).parents('td').attr('store_id')+',';            }else{				storeIds[$(this).val()] = $(this).parents('td').attr('store_id')+',';            }        });        $.post('{pigcms{:U("Shop/change")}', {'did':did, 'type':1,'merIds':merIds,'storeIds':storeIds}, function(res){            if (res.status == 1) {                location.reload();            } else {                alert(res.info);            }        }, 'json');    });    $('#offline').click(function(){        var merIds = [];		var storeIds = {};        $("input[name='merIds[]']:checked").each(function(){            merIds.push($(this).val());            if (storeIds[$(this).val()]) {				storeIds[$(this).val()] += $(this).parents('td').attr('store_id')+',';            }else{				storeIds[$(this).val()] = $(this).parents('td').attr('store_id')+',';            }        });        $.post('{pigcms{:U("Shop/change")}', {'did':did, 'type':0,'merIds':merIds,'storeIds':storeIds}, function(res){            if (res.status == 1) {                location.reload();            } else {                alert(res.info);            }        }, 'json');    });		$('.choose_store').click(function(){		layer.open({			type: 2,			title: '选择指定店铺',			shadeClose: true,			shade: 0.8,			area: ['800px', '600px'],			offset: '200px',			content: "{pigcms{:U('discount_choose_store')}&mer_id="+$(this).data('mer_id')+'&store_ids='+$('.storeIds_'+$(this).data('mer_id')).val()		}); 	});});function choose_store_callfunc(store_ids,store_names,mer_id){	$('.storeIds_'+mer_id).val(store_ids);	if($('.storeNames_'+mer_id).size() > 0){		$('.storeNames_'+mer_id).html(store_names);	}else{		$('.storeIds_'+mer_id).after('<p class="storeNames_'+mer_id+'">'+store_names+'</p>');	}	$('.mer_id_'+mer_id).prop('checked',true);	layer.closeAll();}</script><include file="Public:footer"/>